```

### Approach E: Using `type.pipe()` on the scope

```ts
const IsoDate = type.pipe(
    type("string"),
    (s, ctx) => {
        if (!isoDatePattern.test(s)) return ctx.error("an ISO date string (YYYY-MM-DD)");
